import math

def tau(n):
    """Calculates the number of divisors of n, tau(n)."""
    if n <= 0:
        return 0
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

N_max = 2000
L_max = N_max + 735

matching_pairs = []
results = {} # Store {k: [list of n values]}

for n in range(1, N_max + 1):
    tau_n = tau(n)
    tau_n_plus_735 = tau(n + 735)

    if tau_n == tau_n_plus_735:
        k = tau_n
        a = k - 2

        if k not in results:
            results[k] = []
        results[k].append(n)

        matching_pairs.append((n, k, a))

# Find the minimum non-negative 'a'
min_a = float('inf')
found_a_values = set()

for k in results:
    a = k - 2
    if a >= 0:
        found_a_values.add(a)
        min_a = min(min_a, a)

print(f"Total matching pairs found: {len(matching_pairs)}")
print(f"All matching pairs (n, tau(n), a=tau(n)-2): {matching_pairs}")
print(f"All unique non-negative 'a' values found: {sorted(list(found_a_values))}")
print(f"Minimum non-negative 'a' found: {min_a}")
